import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"火水未济","description":"周易折中 - 火水未济","frontmatter":{"title":"火水未济","description":"周易折中 - 火水未济"},"headers":[],"relativePath":"zh/classics/zhezhong/070.md","filePath":"zh/classics/zhezhong/070.md"}'),h={name:"zh/classics/zhezhong/070.md"};function n(d,a,p,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="火水未济" tabindex="-1">火水未济 <a class="header-anchor" href="#火水未济" aria-label="Permalink to “火水未济”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈未济序卦〉：“物不可穷也，故受之以未济终焉。既济矣，物之穷也。物穷而不变，则无不已之理。易者，变易而不穷也。故既济之后，受之以未济而终焉。未济则未穷也，未穷则有生生之义。为卦离上坎下，火在水上，不相为用，故为未济。”</p><p>未济：亨。小狐汔济，濡其尾，无攸利。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>未济，事未成之时也。水火不交，不相为用。卦之六爻皆失其位，故为未济。汔，近也。濡，湿也。汔济而濡尾，犹未济也。占者如此，何所利哉？</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>未济之时，有亨之理，而卦才复有致亨之道，惟在愼处。狐能度水，濡尾则不能济。其老者多疑畏，故履冰而听，惧其陷也。小者则未能畏愼，故勇于济。汔，当为仡，壮勇之状。《书》曰：“仡仡勇夫。”小狐果于济，则濡其尾而不能济也。未济之时，求济之道，当致慎则能亨。若如小狐之果，则不能济也。既不能济，无所利矣。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：天地不交为否，否不曰亨，否不通也。水火不交为未济，非不济也，未焉尔。故曰“未济亨”。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>小狐当从程传之解，汔济当从本义之解。要之是戒人敬愼之意，自始济以至于将济，不可一息而忘敬愼也。</p><p>象曰：火在水上，未济；君子以愼辨物居方</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>水火异物，各居其所，故君子观象而审辨之。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>水火不交，不相济为用，故为未济。火在水上，非其处也。君子观其处不当之象，以愼处于事物，辨其所当，各居其方，谓止于其所也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰 ：火上水下，各居其所，未济也。君子观此，愼辨万物。有辨然后有交，有未济乃有既济。而末济含既济之象。</p></li><li><p>何氏楷曰 ：愼辨物者，物以群分也；愼居方者，方以类聚也。</p></li></ul><p>彖曰：未济 亨，柔得中也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>指六五言</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>以卦才言也。所以能亨者，以柔得中也。五以柔居尊位，居刚而应刚，得柔之中也。刚柔得中，处未济之时，可以亨也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>蔡氏渊曰：既济之后必乱，故主在下卦而亨取二；未济之后必济，故主在上卦而亨取五。</li></ul><p>小狐汔济，未出中也；濡其尾，无攸利；不续终也</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>据二而言也。二以刚阳居险中，将济者也。又上应于五，险非可安之地，五有当从之理，故果于济如小狐也。既果于济，故有濡尾之患，未能出于险中也。其进锐者其退速，始虽勇于济，不能继续而终之，无所往而利也。虽阴阳不当位，然刚柔皆相应，当未济而有与，若能重慎，则有可济之理。二以汔济，故濡尾也。卦之诸爻皆不得位，故为未济。杂卦云：“未济，男之穷也”，谓三阳皆失位也。斯义也，闻之成都隠者。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云：“小狐汔济”，“汔”字训几，与井卦同。既曰几，便是未出坎中。</p></li><li><p>郭氏鹏海曰：既济之吉以柔得中，未济之亨亦以柔得中，则敬慎胜也。既济之乱以终止，未济之无攸利以不续终，则克终难也。既济之贞以刚柔正，未济之可济以刚柔应，则交济之功也。既曰柔得中，而又有不续终之戒，可见济事无可轻忽之时。既曰不当位，又著刚柔之应，可见得人无不可济之事。</p></li><li><p>呉氏曰慎曰：既济曰“终止则乱”，此曰“无攸利不续终也”。盖事之既济而生乱与未济而无终者，皆一念之怠为之。君子是以贵自强不息。</p></li></ul><p>初六：濡其尾，吝。</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以阴居下，当未济之初，未能自进，故其象占如此。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>六以阴柔在下，处险而应四。处险则不安其居，有应则志行于上。然已既阴柔，而四非中正之才，不能援之以济也。兽之济水必掲其尾，尾濡则不能济。濡其尾，言不能济也。不度其才力而进，终不能济，可羞吝也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏振渊曰：卦辞所谓“小狐”，正指此爻。新进喜事，急于求济，而反不能济，可吝孰甚焉。</li></ul><p>象曰：濡其尾，亦不知极也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>极字未详，考上下韵亦不叶，或恐是“敬”字，今且阙之。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>不度其才力而进，至于濡尾，是不知之极也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏振渊曰 ：事必敬始而后可善其用于终。初所以致尾之濡，不是时不可为，心不知敬愼故耳。</li></ul><p>九二：曳其轮，贞吉。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>以九二应六五而居柔得中，为能自止而不进，得为下之正也，故其象占如此。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>在他卦，九居二为居柔得中，无过刚之义也。于未济，圣人深取卦象以为戒，眀事上恭顺之道。未济者，君道艰难之时也。五以柔处君位，而二乃刚阳之才而居相应之地，当用者也。刚有陵柔之义，水有胜火之象。方艰难之时，所赖者才臣耳，尤当尽恭顺之道。故戒“曵其轮”则得正而吉也。倒曵其轮，杀其势，缓其进，戒用刚之过也。刚过则好犯上而顺不足。唐之郭子仪、李晟，当艰危未济之时，能极其恭顺，所以为得正而能保其终吉也。于六五则言其贞吉，光辉尽君道之善；于九二则戒其恭顺，尽臣道之正，尽上下之道也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>潘氏梦旗曰：九二刚中，力足以济者也。然身在坎中，未可以大用，故曵其车轮，不敢轻进，待时而动，乃为吉也。不量时度力而勇于赴难，适以败事矣。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>既济之时，初二两爻犹未敢轻济，况未济乎？故此爻“曳轮”之戒与既济同，而差一位者，时不同也。观此初二两爻，“濡其尾”则吝，而“曳其轮”则吉，可知既济之初所谓“濡其尾”者，非自止不进之谓也。</p><p>象曰：九二贞吉，中以行正也</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>九居二本，非正以中，故得正也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>九二得正而吉者，以曳轮而得中道，乃正也。案程子言正未必中，中无不正，故凡九二六五皆非正也，而多言贞吉者，以其中也。惟此象传释义最明。</p><p>六三：未济，征凶，利涉大川。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>阴柔不中正，居未济之时，以征则凶。然以柔乘刚，将出乎坎，有利涉之象，故其占如此。葢行者可以水浮而不可以陆走也。或疑“利”字上当有“不”字。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>未济征凶，谓居险无出险之用而行则凶也。必出险而后可征，三以阴柔不中正之才而居险，不足以济，未有可济之道出险之用而征，所以凶也。然未济有可济之道，险终有出险之理，上有刚阳之应，若能渉险而往从之，则济矣。故利涉大川也。然三之阴柔，岂能出险而往？非时不可，才不能也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>赵氏汝梅曰：三居未济之终，过此则近于济矣，故特表以卦名也。</p></li><li><p>胡氏炳文曰：六三居坎上，可以出险。阴柔非能济者，故明言“未济征凶”。案此爻之义最为难眀。葢上下卦之交有济之义。既济之三刚也，故能济；未济之三柔也，故未能济。传曰“其柔危，其刚胜”邪？于此两爻见之矣。又既、未济两卦爻辞未有举卦名者，独此爻曰“未济”。葢他爻之既济、未济者时也，顺时以处之而已；此爻时可济矣而未能济，是未济在己而不在时，故言“未济”，见其失时也。无济之才，故于征则凶；有畏愼之心，故于步大川则利。葢渉大川不可以轻进，未济无阳也。圣人之戒失时而又欲人审于赴时也如此。</p></li></ul><p>象曰：未济征凶，位不当也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>三征则凶者，以位不当也。谓阴柔不中正，无济险之才也。若能涉险以从应，则利矣。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>吴氏澄曰 ：未济诸爻皆位不当，而独于六三言之，以未济由六三故也。</p></li><li><p>俞氏琰曰 ：六爻皆位不当，而独于六三曰位不当，以六三才弱而处下体之上也。</p></li></ul><p>九四：贞吉，悔亡，震用伐鬼方，三年有赏于大国。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>以九居四，不正而有悔也。能勉而贞，则悔亡矣。然以不贞之资，欲勉而贞，非极其阳刚，用力之久不能也。故为伐鬼方三年而受赏之象。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>九四阳刚，居大臣之位，上有虚中眀顺之主，又已出于险，未济已过中矣，有可济之道也。济天下之艰难，非刚健之才不能也。九虽阳而居四，故戒以贞固则吉而悔亡，不贞则不能济，有悔者也。震动之极也，古之人用力之甚者伐鬼方也，故以为义。力勤而远伐，至于三年然后成功，而行大国之赏，必如是乃能济也。济天下之道，当贞固如是。四居柔，故设此戒。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰：“震用伐鬼方”者，震动而使之惊畏也。《诗·时迈》云：“薄言震之，莫不震叠。”与此“震”同。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><ul><li><p>此伐鬼方亦与既济同而差一位也。“三年克之”是已克也，“震用伐鬼方”是方伐也。“三年有赏于大国”，言三年之间赏劳师旅者不绝，非谓事定而论赏也，与《师》之“王三锡命”同，不与《师》之“大君有命”同。</p></li><li><p>三四非君位而以髙宗之事言者，葢《易》中有论时者，则不论其位。如《泰》之论平陂之运而利于艰贞，《革》之论变革之道而宜于改命，皆以上下卦之交时义论之也。</p></li></ul><p>象曰：贞吉悔亡，志行也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>如四之才与时合，而加以贞固，则能行其志，吉而悔亡。鬼方之伐，贞之至也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：爻以六三为未济，则九四其济矣，是以其志行也。</li></ul><p>六五：贞吉，无悔，君子之光，有孚吉。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以六居五，亦非正也。然文明之主居中，应刚，虚心以求下之助，故得贞而吉，且无悔。又有光辉之盛，信实而不妄，吉而又吉也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>五，文明之主，居刚而应刚，其处得中，虚其心而阳为之辅。虽以柔居尊，处之至正至善，无不足也。既得贞正，故吉而无悔。贞其固有，非戒也。以此而济，无不济也。五文明之主，故称其光。君子徳辉之盛而功实称之，有孚也。上云“吉以贞”也，柔而能贞，徳之吉也；下云“吉以功”也，既光而有孚，时可济也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏万里曰：六五逢未济之世，而光辉何也？日之在夏，曀之益热；火之在夜，宿之弥炽。六五变未济为既济，文明之盛，又何疑焉。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>易卦有“悔亡无悔”者，必先悔亡而后无悔。葢无悔之义进于悔亡也。其四五两爻相连言之者，则咸、大壮及此卦是也。此卦自下卦而上卦，事已过中，向乎济之时也。以髙宗论之，四其奋伐荆楚之时，而五其嘉靖殷邦之候乎。凡自晦而明，自剥而生，自乱而治者，其光辉必倍于常时。观之雨后之日光，焚馀之山色，可见矣。</p><p>象曰：君子之光，其晖吉也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>晖者，光之散也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>光盛则有晖，晖光之散也。君子积充而光盛，至于有晖，善之至也，故重云吉。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏振渊曰 ：光而言晖，昭其盛也。贞吉之吉，吉在五；晖吉之吉，吉在天下。</li></ul><p>上九：有孚于饮酒，无咎。濡其首，有孚失是。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>以刚明居未济之极时，将可以有为而自信自养，以俟命，无咎之道也。若纵而不反，如狐之渉水而濡其首，则过于自信而失其义矣。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>九以刚在上，刚之极也。居月之上，明之极也。刚极而能明，则不为躁而为决，明能烛理，刚能断义。居未济之极，非得济之位，无可济之理，则当乐天顺命而已。若否终则有倾时之变也，未济则无极而自济之理。故止为未济之极，至诚安于义命而自乐，则可无咎。饮酒自乐也，不乐其处则忿躁陨获，入于凶咎矣。若从乐而耽肆，过礼至濡其首，亦非能安其处也。有孚，自信于中也。失是，失其宜也。如是，则于有孚为失也。人之处患难，知其无可奈何而放意不反者，岂安于义命者哉？</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏牧曰：既济以柔居上，止则乱也，故濡其首厉。未济以刚居上，穷则通矣，故有孚于饮酒无咎。</p></li><li><p>石氏介曰：上九以刚眀之徳，是内有孚也。在未济之终，终又反于既济，故得饮酒自乐。若乐而不知节，复濡其首，则虽有孚，必失于此。此戒之之辞也。</p></li><li><p>丘氏富国曰：既言饮酒之无咎，复言饮酒濡首之失，何也？葢饮酒可也，耽饮而至于濡首，则昔之有孚者，今失于是矣。</p></li><li><p>李氏简曰：未济之终，甫及既济，而复以濡首戒之，惧以终始。其要无咎，此之谓易之道也。</p></li></ul><p>象曰：饮酒濡首，亦不知节也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>饮酒至于濡首，不知节之甚也。所以至如是不能安义命，能安则不失其常矣。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖达曰 ：释饮酒所以致濡首之难，以其不知止节故也。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>既济之上，彖所谓终乱；未济之上，则彖所谓汔济者也。缘尾之象在初，故此不用濡尾之义，但戒以不可濡首而失其节，则犹之不续终之意也。</p><p>总论</p><ul><li><p>郑氏汝谐曰：既济初吉终乱，未济则初乱终吉。以卦之体言之，既济则出明而之险，未济则出险而之明。以卦之义言之，济于始者必乱于终，乱于始者必济于终。天之道，物之理，固然也。</p></li><li><p>丘氏富国曰：内三爻坎险也，初言濡尾之吝，二言曳轮之贞，三有征凶位不当之戒，皆未济之事也。外三爻离眀也，四言伐鬼方有赏，五言君子之光有孚，上言饮酒无咎，则未济为既济矣。</p></li><li><p>万氏善曰：泰之变为既济，否之变为未济。葢既济自泰而趋否者也，未济自否而趋泰者也。故既济爻辞无吉者，以其趋于否也；未济爻辞多吉，以其趋于泰也。否泰者治乱对待之理，既未济者否泰变更之渐也。</p></li><li><p>呉氏曰：愼曰易之为义，不易也，交易也变易也。乾坤之纯不易者也，既济未济交易变易者也。以是始终，易之大义。</p></li></ul>',117)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
